changeSet.sql:
alter table kb_tree_file add column if not exists ishead boolean default true;
alter table kb_tree_file add column if not exists version integer default 0;
alter table kb_tree_file add column if not exists previousVersion bigint references kb_tree_file(id);

update kb_tree_file set oid =nextval('resourceid_sequence') where oid is null

update kb_classifier set default_structure = true where uniquename='status' or uniquename = 'type' or uniquename='document type' or uniquename='file type';
update kb_classifier set searchable = true where uniquename='status' or uniquename = 'type' or uniquename='document type' or uniquename='file type' or uniquename='site name' or uniquename='property';

update kb_attribute set default_structure = true where lower(name) = 'effective date';
update kb_attribute set searchable = true where lower(name)='unit' or lower(name) = 'effective date';

alter table wf_launcher add column if not exists alias character varying(64);
alter table wf_launcher add column if not exists lastmodifieddate  timestamp with time zone  default now();
alter table wf_launcher add column if not exists creationdate      timestamp with time zone  default now();
alter table wf_launcher add column if not exists lastmodifieduser  bigint REFERENCES users(id) ON DELETE RESTRICT;
alter table wf_launcher add column if not exists state             integer default 1;

alter table wf_procedure drop constraint if exists lastmodifieduser_fk;
alter table wf_procedure add constraint lastmodifieduser_fk FOREIGN KEY (lastmodifieduser) REFERENCES users(id) ON DELETE RESTRICT;

create table if not exists kb_user_list( id bigint primary key, lastmodifieddate timestamp with time zone default now(), creationdate timestamp with time zone default now(), lastmodifieduser bigint references users(id) on delete set null, state integer default 1, domain_id bigint references domain(id) on delete cascade, owner_id bigint references users(id) on delete cascade, console character varying(256) not null, title character varying(2048) not null, description character varying(2048) );
create table if not exists kb_user_list_item ( id bigint primary key, lastmodifieddate timestamp with time zone default now(), creationdate timestamp with time zone default now(), lastmodifieduser bigint references users(id) on delete set null, state integer default 1, domain_id bigint references domain(id) on delete cascade, userlist_id bigint references kb_user_list(id) on delete cascade, content_id bigint references content(id) on delete set null, datasetmember_id bigint references datasetmember(id) on delete set null, user_id bigint references users(id) on delete set null );
create table if not exists kb_userlistclassification ( id bigint primary key, classifier_id bigint references kb_classifier(id) on delete restrict, datasetmember_id bigint references datasetmember(id) on delete restrict, position integer default 0, user_list_item_id bigint references kb_user_list_item on delete cascade );

alter table kb_user_list_item add column if not exists title character varying(1024);
alter table kb_user_list_item add column if not exists  type integer default 1;
alter table kb_user_list_item add column if not exists version_match integer default 0;
alter table kb_user_list add column if not exists total_items integer default 0;

 			alter table domain add column if not exists encrypt_files boolean default false;
 			update domain set encrypt_files=false;
			alter table domain alter column encrypt_files set not null;

 				alter table savedquery add column if not exists 	lastmodifieddate          timestamp with time zone default now();
				alter table savedquery add column if not exists		creationdate              timestamp with time zone default now();
				alter table savedquery add column if not exists     lastmodifieduser          bigint  references users(id) on delete set null;
				alter table savedquery add column if not exists	    state                     integer default 1;
				alter table savedquery add column if not exists	    domain_id                 bigint  references domain(id) on delete cascade;

update users set locale_str='en' where locale_str is null;
update users set  timezone=' US/Central' where timezone is null;
update users set  timezone=' US/Central' where timezone is null;
update users set creationdate=lastmodifieddate where creationdate is null;
update users set passwordlastmodifieddate=creationdate where passwordlastmodifieddate is null;
